"""Publish the verified install-and-run walkthrough with chapters and capture evidence."""
from pathlib import Path
import json,html,hashlib,shutil
R=Path(__file__).resolve().parents[1];N='managed-agents-install-run-walkthrough';P=R/'presentations'/N;V=R/'videos'/N
TITLE='Install and Run the Claude Managed Agents Learning Platform'
r=json.loads((V/'validation.json').read_text(encoding='utf-8'));assert r['fullVideoAndAudioDecode']=='passed';assert hashlib.sha256((V/r['file']).read_bytes()).hexdigest()==r['sha256']
t=json.loads((V/'timeline.json').read_text(encoding='utf-8'));story=json.loads((P/'storyboard.json').read_text(encoding='utf-8'));shutil.copy2(P/'platform/capture-evidence.json',V/'walkthrough-evidence.json');e=json.loads((V/'walkthrough-evidence.json').read_text(encoding='utf-8'))
assert len(t['slides'])==len(story)==33 and not e['errors'] and not e['liveExecution']
shutil.copy2(P/'.build/video/slides/slide-01.png',V/'cover.png')
